import itertools
import json

def solve():
    houses = list(range(6))  # indices 0..5 for houses 1..6

    names = ["Bob", "Peter", "Eric", "Alice", "Arnold", "Carol"]
    hair_colors = ["auburn", "blonde", "brown", "black", "red", "gray"]
    heights = ["very tall", "average", "very short", "tall", "super tall", "short"]

    def safe_set(arr, idx, val):
        if arr[idx] is None:
            arr[idx] = val
            return True
        return arr[idx] == val

    for name_assign in itertools.permutations(names):
        # Clue 2: Alice is in the fourth house.
        if name_assign[3] != "Alice":
            continue

        # Convenience indices
        idx_name = {n: name_assign.index(n) for n in names}

        # Clue 1 + 8: Blonde is directly left of Bob AND blonde is Carol => Carol is directly left of Bob.
        if idx_name["Bob"] != idx_name["Carol"] + 1:
            continue

        # Clue 9 + 12 + 6: One house between gray (house 3) and red; red is Eric => Eric at house 1 or 5 (indices 0 or 4).
        if idx_name["Eric"] not in (0, 4):
            continue

        # Clue 3 + 4 + 10: Arnold is short; tall is in sixth (idx 5); very short is in fifth (idx 4).
        # Hence Arnold cannot be in houses 5 or 6 (indices 4 or 5).
        if idx_name["Arnold"] in (4, 5):
            continue

        # Bob cannot be in the third house because house 3 has gray hair (Clue 12) and Bob has brown hair (Clue 11).
        if idx_name["Bob"] == 2:
            continue

        # Assign heights with constraints
        base_heights = [None] * 6
        if not safe_set(base_heights, 5, "tall"):  # Clue 4
            continue
        if not safe_set(base_heights, 4, "very short"):  # Clue 10
            continue
        if not safe_set(base_heights, idx_name["Arnold"], "short"):  # Clue 3
            continue
        # Clue 13 + 8: Blonde is very tall and blonde is Carol => Carol is very tall.
        if not safe_set(base_heights, idx_name["Carol"], "very tall"):
            continue

        remaining_height_values = [h for h in heights if h not in base_heights or base_heights.count(h) == 0]
        remaining_houses_for_height = [i for i in houses if base_heights[i] is None]

        # Assign remaining heights (typically 'average' and 'super tall')
        for perm_heights in itertools.permutations(remaining_height_values):
            heights_assign = base_heights[:]
            heights_ok = True
            for i, hval in zip(remaining_houses_for_height, perm_heights):
                if not safe_set(heights_assign, i, hval):
                    heights_ok = False
                    break
            if not heights_ok:
                continue
            # Clue 7: super tall is somewhere to the right of average
            if heights_assign.index("super tall") <= heights_assign.index("average"):
                continue

            # Assign hair colors with constraints
            base_hair = [None] * 6
            # Clue 12: gray hair is in the third house.
            if not safe_set(base_hair, 2, "gray"):
                continue
            # Clue 11: Bob has brown hair.
            if not safe_set(base_hair, idx_name["Bob"], "brown"):
                continue
            # Clue 6: red hair is Eric.
            if not safe_set(base_hair, idx_name["Eric"], "red"):
                continue
            # Clue 8: blonde hair is Carol.
            if not safe_set(base_hair, idx_name["Carol"], "blonde"):
                continue

            # Clue 1: The person who has blonde hair is directly left of Bob.
            if base_hair.index("blonde") + 1 != idx_name["Bob"]:
                continue

            # Assign remaining hair colors
            remaining_hair_values = [c for c in hair_colors if c not in base_hair or base_hair.count(c) == 0]
            remaining_houses_for_hair = [i for i in houses if base_hair[i] is None]

            for perm_hair in itertools.permutations(remaining_hair_values):
                hair_assign = base_hair[:]
                hair_ok = True
                for i, cval in zip(remaining_houses_for_hair, perm_hair):
                    if not safe_set(hair_assign, i, cval):
                        hair_ok = False
                        break
                if not hair_ok:
                    continue

                # Clue 5: black hair is not in the fourth house.
                if hair_assign[3] == "black":
                    continue

                # Clue 9: one house between gray and red
                if abs(hair_assign.index("gray") - hair_assign.index("red")) != 2:
                    continue

                # Clue 13: blonde hair person is very tall
                if heights_assign[hair_assign.index("blonde")] != "very tall":
                    continue

                # All constraints satisfied; build rows
                rows = []
                for h in range(6):
                    rows.append([str(h + 1), name_assign[h], hair_assign[h], heights_assign[h]])
                return rows

    return None

def main():
    rows = solve()
    if rows is None:
        result = {
            "solution": {
                "header": ["House", "Name", "HairColor", "Height"],
                "rows": []
            }
        }
    else:
        result = {
            "solution": {
                "header": ["House", "Name", "HairColor", "Height"],
                "rows": rows
            }
        }
    print(json.dumps(result, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    main()
